/**
 * Parity check for the path-ignore port.
 *
 * The cleaned line totals are only as trustworthy as this predicate, so it is
 * checked against the Python original rather than against my own expectations.
 *
 *   npx tsx scripts/verify-ignore-globs.ts <py_ignore.json>
 *
 * The baseline file is { "<path>": <boolean> }, generated by running
 * _path_is_ignored from github_work_report.py over the same paths.
 */
import { readFileSync } from "node:fs";
import { isIgnoredPath } from "../lib/github/stats";
import { DEFAULT_STAT_IGNORE_GLOBS } from "../lib/config/schema";

const path = process.argv[2];
if (!path) {
  console.error("Usage: npx tsx scripts/verify-ignore-globs.ts <baseline.json>");
  process.exit(1);
}

const baseline = JSON.parse(readFileSync(path, "utf8")) as Record<string, boolean>;
let mismatches = 0;

for (const [file, expected] of Object.entries(baseline)) {
  const actual = isIgnoredPath(file, DEFAULT_STAT_IGNORE_GLOBS);
  const mark = actual === expected ? "ok  " : "FAIL";
  if (actual !== expected) mismatches += 1;
  console.log(`${mark} ${String(actual).padEnd(5)} ${JSON.stringify(file)}`);
}

console.log(`\n${Object.keys(baseline).length} paths checked, ${mismatches} mismatches`);
process.exit(mismatches ? 1 : 0);
